Predicate<String> lengthFilter = s -> s.length() > 3;
Predicate<String> startsWithA = s -> s.startsWith("A");
Predicate<String> filter = lengthFilter.and(startsWithA.negate());
System.out.println(filter.test("Alice") + " " + filter.test("Charlie"));

Function<Integer, Integer> add = x -> x + 2;
Function<Integer, Integer> multiply = x -> x * 3;
Function<Integer, Integer> combined = add.andThen(multiply);
System.out.println(combined.apply(5));

Function<Integer, Integer> add = x -> x + 2;
Function<Integer, Integer> multiply = x -> x * 3;
Function<Integer, Integer> combined = add.compose(multiply);
System.out.println(combined.apply(5));

@FunctionalInterface
interface CustomFilter {
    boolean test(String s);
    boolean equals(Object obj);
    String toString();
}

