Function<String, String> addPrefix = s -> "Prefix_" + s;
Function<String, String> addSuffix = s -> s + "_Suffix";
Function<String, String> pipeline = addPrefix.compose(addSuffix);
System.out.println(pipeline.apply("Data"));
